from pathlib import Path
p=Path('scripts/write_story.py');s=p.read_text(encoding='utf8');s=s.replace('这也解释了为什么追不到彩虹。它的尽头，没有藏在某一棵树或某一座山后。','这也解释了为什么追不到彩虹。你一直往前走，接到阳光的水滴就一直在换。').replace('让太阳在身后，缓慢调整你和水雾的位置。亮起颜色的地方，会随着你移动。','背对太阳，缓慢调整你和水雾的位置。你会发现，彩虹会随着你的移动而改变。').replace('从一滴水，到满天雨幕，再到你的眼睛。彩虹，就是阳光送来的一封，有角度的信。','一滴滴雨水，把不同颜色的光送到你的眼前。你站的位置，决定了天空里那条彩虹。');p.write_text(s,encoding='utf8')
